\mathrm{df\text{-}metric\text{-}open\text{-}code}\vdash\;\begin{aligned}
\mathsf{OpenCode}_{\mathcal A}(U)&\leftrightarrow\mathsf{Met}(\mathcal A)\land U\subseteq N\times_N(A\times_N\mathbb Q_c^+),\\
x\in_{\mathcal A}U&\leftrightarrow\mathsf{Pt}_{\mathcal A}(x)\land\mathsf{OpenCode}_{\mathcal A}(U)\land\exists n\exists a\in A\exists r\in\mathbb Q_c^+\;[\tau(n,a,r)\in U\land\delta_{\mathcal A}(x,\widehat a_{\mathcal A})<_R\widehat r],\\
(a,r)\ll_{\mathcal A}(b,s)&\leftrightarrow a,b\in A\land r,s\in\mathbb Q_c^+\land D_{ab}+_R\widehat r<_R\widehat s,\\
(a,r)\ll_{\mathcal A}U&\leftrightarrow\mathsf{OpenCode}_{\mathcal A}(U)\land\exists n\exists b\in A\exists s\in\mathbb Q_c^+\;[\tau(n,b,s)\in U\land(a,r)\ll_{\mathcal A}(b,s)].
\end{aligned}
